WITH RankedPosts AS (SELECT p.Id AS PostId, p.Title, p.CreationDate, p.ViewCount, p.Score, ROW_NUMBER() OVER (PARTITION BY p.PostTypeId ORDER BY p.Score DESC NULLS FIRST) AS PostRank, COALESCE(SUM(v.BountyAmount) FILTER(WHERE v.VoteTypeId = 8) OVER (PARTITION BY p.Id), 0) AS TotalBounty FROM Posts AS p LEFT JOIN Votes AS v ON p.Id = v.PostId WHERE p.CreationDate >= CAST('2024-10-01' AS Nullable(DATE)) - INTERVAL '1' YEAR), PostComments AS (SELECT c.PostId, COUNT(c.Id) AS CommentCount, GROUP_CONCAT(c.Text, '; ') AS CommentTexts FROM Comments AS c GROUP BY c.PostId), PostHistories AS (SELECT ph.PostId, MAX(CASE WHEN ph.PostHistoryTypeId = 10 THEN ph.CreationDate END) AS LastClosedDate FROM PostHistory AS ph GROUP BY ph.PostId) SELECT rp.PostId, rp.Title, rp.CreationDate, rp.ViewCount, rp.Score, rp.PostRank, pc.CommentCount, pc.CommentTexts, ph.LastClosedDate, rp.TotalBounty FROM RankedPosts AS rp LEFT JOIN PostComments AS pc ON rp.PostId = pc.PostId LEFT JOIN PostHistories AS ph ON rp.PostId = ph.PostId WHERE rp.PostRank <= 5 AND (ph.LastClosedDate IS NULL OR ph.LastClosedDate < CAST('2024-10-01' AS Nullable(DATE)) - INTERVAL '30' DAYS) ORDER BY rp.Score DESC NULLS FIRST, rp.ViewCount DESC NULLS FIRST